<template><LnPopover><template #trigger><button class="property-trigger ln-focus-ring" type="button"><span class="property-icon" :style="{color:selected?.color}">{{selected?.icon||'○'}}</span><span class="property-label">{{selected?.label||placeholder}}</span><span class="property-caret">⌄</span></button></template><template #default="{close}"><div class="property-list"><span class="property-title">{{title}}</span><button v-for="option in options" :key="option.value" type="button" :class="{'is-selected':modelValue===option.value}" @click="choose(option,close)"><i :style="{color:option.color}">{{option.icon||'●'}}</i><span>{{option.label}}</span><small v-if="option.description">{{option.description}}</small><b v-if="modelValue===option.value">✓</b></button></div></template></LnPopover></template>
<script setup lang="ts">
import {computed} from 'vue';import LnPopover from './LnPopover.vue';import type{LnOption}from'./types';const props=withDefaults(defineProps<{modelValue?:string;options:LnOption[];title?:string;placeholder?:string}>(),{title:'选择属性',placeholder:'未设置'});const emit=defineEmits<{(e:'update:modelValue',value:string):void}>();const selected=computed(()=>props.options.find(o=>o.value===props.modelValue));function choose(option:LnOption,close:()=>void){emit('update:modelValue',option.value);close()}
</script>
<style scoped lang="scss">
.property-trigger{height:28px;padding:0 7px;display:inline-flex;align-items:center;gap:6px;border:1px solid transparent;border-radius:5px;background:transparent;color:var(--ln-text-secondary);font:12px/1 var(--ln-font);cursor:pointer;&:hover{border-color:var(--ln-border);background:var(--ln-surface-hover)}}.property-icon{width:14px;display:inline-grid;place-items:center;flex:0 0 14px;font-size:13px;line-height:1}.property-label{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:16px}.property-caret{flex:0 0 auto;color:var(--ln-text-tertiary);line-height:1}.property-list{width:230px;display:grid;gap:2px;font-family:var(--ln-font)}.property-title{padding:6px 8px;color:var(--ln-text-tertiary);font-size:10px;font-weight:600;text-transform:uppercase;letter-spacing:.06em}.property-list button{min-height:34px;padding:6px 8px;display:grid;grid-template-columns:18px 1fr auto;align-items:center;gap:7px;border:0;border-radius:5px;background:transparent;color:var(--ln-text);text-align:left;cursor:pointer;&:hover,&.is-selected{background:var(--ln-surface-hover)}i{font-style:normal;text-align:center}span{font-size:12px}small{grid-column:2;color:var(--ln-text-tertiary);font-size:10px}b{grid-column:3;grid-row:1;color:var(--ln-accent);font-size:11px}}
</style>
